using HobbywingCan.Core.DroneCan;
using HobbywingCan.Core.Mavlink;
using HobbywingCan.Core.Messages;

namespace HobbywingCan.Core.Tests;

public class TransportTests
{
    private static byte[] Hex(string s) => Convert.FromHexString(s);

    private const string NodeInfoPayload =
        "e8030000423412010201efbeadde88776655443322110304000102030405060708090a0b0c0d0e0f03010203636f6d2e686f62627977696e672e78386732";

    // Frames for a GetNodeInfo response 5 -> 126, transfer id 3, generated by pydronecan
    private static readonly string[] NodeInfoFrames =
    [
        "1d75e80300004283", "3412010201efbe23", "adde887766554403", "3322110304000123", "0203040506070803",
        "090a0b0c0d0e0f23", "03010203636f6d03", "2e686f6262797723", "696e672e78386703", "3263",
    ];

    [Fact]
    public void CanId_MatchesReference()
    {
        Assert.Equal(0x1F017E85u, CanId.Service(31, 1, request: false, destinationNodeId: 126, sourceNodeId: 5));
        Assert.Equal(0x1FF285FEu, CanId.Service(31, 242, request: true, destinationNodeId: 5, sourceNodeId: 126));
    }

    [Fact]
    public void Reassembler_RebuildsMultiFrameTransferAndChecksCrc()
    {
        var r = new TransferReassembler();
        Transfer? result = null;
        foreach (var hex in NodeInfoFrames)
        {
            result = r.Accept(new CanFrame(0x1F017E85, Hex(hex)), 0) ?? result;
        }

        Assert.NotNull(result);
        Assert.Equal(TransferKind.Response, result.Kind);
        Assert.Equal(1, result.DataTypeId);
        Assert.Equal(5, result.SourceNodeId);
        Assert.Equal(126, result.DestinationNodeId);
        Assert.Equal(3, result.TransferId);
        Assert.Equal(Hex(NodeInfoPayload), result.Payload);
        Assert.Equal(0, r.CrcErrors);
    }

    [Fact]
    public void Reassembler_RejectsCorruptedPayload()
    {
        var r = new TransferReassembler();
        var frames = NodeInfoFrames.Select(Hex).ToArray();
        frames[4][0] ^= 0xFF;
        foreach (var f in frames)
        {
            Assert.Null(r.Accept(new CanFrame(0x1F017E85, f), 0));
        }
        Assert.Equal(1, r.CrcErrors);
    }

    [Fact]
    public void Encoder_ProducesReferenceFrames()
    {
        var frames = TransferEncoder.Encode(0x1F017E85, 3, Hex(NodeInfoPayload), DataTypes.GetNodeInfo.Signature);
        Assert.Equal(NodeInfoFrames, frames.Select(f => Convert.ToHexString(f.Data).ToLowerInvariant()));

        var single = TransferEncoder.Encode(0x1FF285FE, 9, HwMajorConfig.EncodeRequest(), DataTypes.HwGetMajorConfig.Signature);
        Assert.Equal("00c9", Convert.ToHexString(Assert.Single(single).Data).ToLowerInvariant());
    }

    [Fact]
    public async Task Node_RequestIsAnsweredBySimulatedEsc()
    {
        var bus = new LoopbackEsc(escNodeId: 3, majorConfig: Hex("851e752c01aa55"));
        using var node = new DroneCanNode(bus, localNodeId: 126);

        var response = await node.RequestAsync(DataTypes.HwGetMajorConfig, 3, HwMajorConfig.EncodeRequest(), TimeSpan.FromSeconds(1));

        Assert.NotNull(response);
        Assert.Equal(5, HwMajorConfig.Decode(response.Payload).ThrottleChannel);
        var request = Assert.Single(bus.Sent);
        Assert.Equal(126, CanId.SourceNodeId(request.Id));
        Assert.Equal(TransferKind.Request, CanId.Kind(request.Id));
    }

    [Fact]
    public async Task Node_RequestTimesOutWithoutResponse()
    {
        var bus = new LoopbackEsc(escNodeId: 3, majorConfig: Hex("851e752c01aa55"));
        using var node = new DroneCanNode(bus, localNodeId: 126);

        var response = await node.RequestAsync(DataTypes.HwGetMajorConfig, 9, [0], TimeSpan.FromMilliseconds(50));

        Assert.Null(response);
    }

    [Fact]
    public void Mavlink_CanFrameRoundTrip()
    {
        var encoder = new MavlinkEncoder(255, 190);
        var payload = MavlinkMessages.EncodeCanFrame(1, 1, 0, 0x9FF285FE, Hex("00c9"));
        var bytes = encoder.Encode(MavlinkIds.CanFrame, payload);

        var parser = new MavlinkParser();
        // feed with junk in front and split in two chunks to exercise resync and buffering
        var packets = parser.Push(new byte[] { 0x00, 0xFD, 0x13 }).Concat(parser.Push(bytes.AsSpan(0, 5))).Concat(parser.Push(bytes.AsSpan(5))).ToList();

        var packet = Assert.Single(packets);
        Assert.Equal(MavlinkIds.CanFrame, packet.MessageId);
        var (id, bus, data) = MavlinkMessages.DecodeCanFrame(packet);
        Assert.Equal(0x9FF285FEu, id);
        Assert.Equal(0, bus);
        Assert.Equal(Hex("00c9"), data);
    }

    [Fact]
    public void Mavlink_HeartbeatMatchesPymavlinkEncoding()
    {
        // HEARTBEAT type=GCS autopilot=INVALID, seq 0, sys 255 comp 190 (pymavlink reference)
        var bytes = new MavlinkEncoder(255, 190).Encode(MavlinkIds.Heartbeat, MavlinkMessages.EncodeHeartbeat(6, 8));
        Assert.Equal("FD09000000FFBE0000000000000006080000035C2B", Convert.ToHexString(bytes));
    }

    [Fact]
    public void Mavlink_CanFrameMatchesPymavlinkEncoding()
    {
        var payload = MavlinkMessages.EncodeCanFrame(1, 1, 0, 0x9FF285FE, Hex("00c9"));
        var bytes = new MavlinkEncoder(255, 190).Encode(MavlinkIds.CanFrame, payload);
        Assert.Equal("FD0A000000FFBE820100FE85F29F0101000200C9F1CA", Convert.ToHexString(bytes));
    }

    /// <summary>Fake bus: answers GetMajorConfig requests addressed to one node, like an ESC would.</summary>
    private sealed class LoopbackEsc(byte escNodeId, byte[] majorConfig) : ICanBus
    {
        public List<CanFrame> Sent { get; } = new();

        public event Action<CanFrame>? FrameReceived;

        public void Send(CanFrame frame)
        {
            Sent.Add(frame);
            if (CanId.Kind(frame.Id) == TransferKind.Request && CanId.DestinationNodeId(frame.Id) == escNodeId &&
                CanId.DataTypeId(frame.Id) == DataTypes.HwGetMajorConfig.Id)
            {
                byte tid = (byte)(frame.Data[^1] & 0x1F);
                uint id = CanId.Service(24, (byte)DataTypes.HwGetMajorConfig.Id, request: false, CanId.SourceNodeId(frame.Id), escNodeId);
                foreach (var f in TransferEncoder.Encode(id, tid, majorConfig, DataTypes.HwGetMajorConfig.Signature))
                {
                    Task.Run(() => FrameReceived?.Invoke(f));
                }
            }
        }
    }
}
